10864	# (wave 26c, D3 / F26-3, F25-1) The tool calls in flight in an engine's event stream, updated per
10865	# complete line ($Open: a HashSet[string] of their keys): codex `item.started` of a
10866	# command_execution, mcp_tool_call or web_search item until its `item.completed` (by the item id;
10867	# an id-less one by its type); agy a `tool` step in state ACTIVE until the same step reports
10868	# another state; muse a task proposed with task_kind tool.* until its task.lifecycle end
10869	# (completed, failed, cancelled, rejected). A line that is not such an event changes nothing.
10870	# (wave 28b, D12) $Labels (optional, key -> text): what an open key names for the stall cut - "codex
10871	# command_execution <id>", "agy tool step <n>", "muse <task kind> <task id>". (wave 29) claude: an
10872	# assistant event's tool_use block until the user event's tool_result with its tool_use_id ("claude
10873	# <tool> <id>").
10874	$script:CodexToolItems = @('command_execution', 'mcp_tool_call', 'web_search')
10875	function Update-ToolFlight {
10876	    param([string]$Engine, [string]$Line, $Open, $Labels = $null)
10877	    $t = ([string]$Line).Trim()
10878	    if (-not $t.StartsWith('{')) { return }
10879	    # a cheap test first: most lines are messages and deltas
10880	    $isCodex = (-not $Engine -or $Engine -eq 'codex')
10881	    if ($isCodex -and $t.IndexOf('command_execution') -lt 0 -and $t.IndexOf('mcp_tool_call') -lt 0 -and $t.IndexOf('web_search') -lt 0) { return }
10882	    if ($Engine -eq 'agy' -and $t.IndexOf('"tool"') -lt 0) { return }
10883	    if ($Engine -eq 'muse' -and $t.IndexOf('task.lifecycle.') -lt 0) { return }
10884	    if ($Engine -eq 'claude' -and $t.IndexOf('tool_use') -lt 0 -and $t.IndexOf('tool_result') -lt 0) { return }
10885	    $obj = $null
10886	    try { $obj = ConvertFrom-Json -InputObject $t } catch { return }
10887	    if ($isCodex) {
10888	        $type = [string](Get-PropertyValue $obj 'type' '')
10889	        if ($type -ne 'item.started' -and $type -ne 'item.completed') { return }
10890	        $it = Get-PropertyValue $obj 'item' $null
10891	        if (-not (Test-IsJsonObject $it)) { return }
10892	        $itype = [string](Get-PropertyValue $it 'type' '')
10893	        if ($script:CodexToolItems -notcontains $itype) { return }
10894	        $id = [string](Get-PropertyValue $it 'id' '')
10895	        if ($type -eq 'item.started') {
10896	            $key = $(if ($id) { "codex:$id" } else { "codex-type:$itype#$($Open.Count)" })
10897	            [void]$Open.Add($key)
10898	            if ($null -ne $Labels) { $Labels[$key] = "codex $itype$(if ($id) { " $id" })" }
10899	            return
10900	        }
10901	        if ($id -and $Open.Contains("codex:$id")) { [void]$Open.Remove("codex:$id"); return }
10902	        $k = @($Open | Where-Object { $_ -like "codex-type:$itype#*" }) | Select-Object -First 1
10903	        if ($k) { [void]$Open.Remove([string]$k) }
10904	        return
10905	    }
10906	    if ($Engine -eq 'agy') {
10907	        if ([string](Get-PropertyValue $obj 'event' '') -ne 'step_update') { return }
10908	        $su = Get-PropertyValue $obj 'step_update' $null
10909	        if (-not (Test-IsJsonObject $su) -or [string](Get-PropertyValue $su 'step_type' '') -ne 'tool') { return }
10910	        $key = "agy:$([string](Get-PropertyValue $su 'step_index' ''))"
10911	        if ([string](Get-PropertyValue $su 'state' '') -eq 'ACTIVE') {
10912	            [void]$Open.Add($key)
10913	            if ($null -ne $Labels) { $Labels[$key] = "agy tool step $([string](Get-PropertyValue $su 'step_index' '?'))" }
10914	        } else { [void]$Open.Remove($key) }
10915	        return
10916	    }
10917	    if ($Engine -eq 'muse') {
10918	        $pType = [string](Get-PropertyValue $obj 'payload_type' '')
10919	        if ($pType -notlike 'task.lifecycle.*') { return }
10920	        $payload = Get-PropertyValue $obj 'payload' $null
10921	        $ev = Get-PropertyValue $payload 'event' $null
10922	        $tid = [string](Get-PropertyValue $ev 'task_id' '')
10923	        if (-not $tid) { $tid = [string](Get-PropertyValue $payload 'task_id' '') }
10924	        if (-not $tid) { return }
10925	        if ($pType -eq 'task.lifecycle.proposed') {
10926	            $kind = [string](Get-PropertyValue $ev 'task_kind' '')
10927	            if ($kind -like 'tool.*') {
10928	                [void]$Open.Add("muse:$tid")
10929	                if ($null -ne $Labels) { $Labels["muse:$tid"] = "muse $kind $tid" }
10930	            }
10931	            return
10932	        }
10933	        if (@('task.lifecycle.completed', 'task.lifecycle.failed', 'task.lifecycle.cancelled', 'task.lifecycle.canceled', 'task.lifecycle.rejected') -contains $pType) { [void]$Open.Remove("muse:$tid") }
10934	        return
10935	    }
10936	    if ($Engine -eq 'claude') {
10937	        $type = [string](Get-PropertyValue $obj 'type' '')
10938	        if ($type -ne 'assistant' -and $type -ne 'user') { return }
10939	        $msg = Get-PropertyValue $obj 'message' $null
10940	        foreach ($b in @(Get-PropertyValue $msg 'content' @())) {
10941	            if (-not (Test-IsJsonObject $b)) { continue }
10942	            $bt = [string](Get-PropertyValue $b 'type' '')
10943	            if ($type -eq 'assistant' -and $bt -eq 'tool_use') {
10944	                $id = [string](Get-PropertyValue $b 'id' '')
10945	                if (-not $id) { continue }
10946	                [void]$Open.Add("claude:$id")
10947	                if ($null -ne $Labels) { $Labels["claude:$id"] = "claude $([string](Get-PropertyValue $b 'name' 'tool')) $id" }
10948	            } elseif ($type -eq 'user' -and $bt -eq 'tool_result') {
10949	                $tid = [string](Get-PropertyValue $b 'tool_use_id' '')
10950	                if ($tid) { [void]$Open.Remove("claude:$tid") }
10951	            }
10952	        }
10953	    }
10954	}
10955	
10956	# (wave 26b, D10, D12) Waits for an engine turn's process: its wall-clock limit ($TimeoutSec), the
10957	# stall cut ($StallSec > 0: no output appended to $EventsPath for that long while the process
10958	# lives - the codex --json items, agy's stream-json, muse's MSP records all go to that file; the
10959	# clock starts with the turn) and the operator's kick ($KickPath appears).
10960	# (wave 26c, D3) The silent timer resets on ANY growth of the stream (bytes, not complete lines)
10961	# and is SUSPENDED while a tool call is in flight (Update-ToolFlight over $Engine's events): a
10962	# member running one long command is never cut; the timeout stays the hard bound.
10963	# (wave 26c, D1) The kick file is checked before the wait loop, on every poll and ONCE MORE after
10964	# the process exited: a kick found then is taken as LATE (KickLate - the outcome stays); every
10965	# taken kick is acknowledged (Confirm-Kick).
10966	# Polls every second (TEST HOOK: CODEX_CONSULT_TEST_WAIT_TICK_MS). Kills nothing - the caller
10967	# stops the tree. { Exited; Reason ('' | 'timeout' | 'stall' | 'kick'); KickLate; Events (lines
10968	# seen); LastEvent (DateTimeOffset of the last line seen, $null when none); Silent (seconds
10969	# without output outside a tool call at the stall cut); ToolWait (seconds the timer was suspended
10970	# for tool calls) }.
10971	# (wave 27c, D5) Oversized: the event lines longer than 1 MiB skipped by the bounded reader.
10972	# (wave 28b, D12 / F36-11, F32-7) A tool call cannot suspend the stall timer for ever, and no
10973	# completion event is needed to end the suspension: while a tool call is open, the stream must still
10974	# GROW - once it has not grown for 2 x -StallSec (TEST HOOK, test mode only:
10975	# CODEX_CONSULT_TEST_TOOL_CAP_SEC = that bound in seconds; no floor) the suspension ends and the
10976	# stall cut follows, naming the open call: ToolOpen = the seconds the tool call(s) had been open (0
10977	# when the cut was an ordinary one), OpenTools = what they were ("codex command_execution item_3",
10978	# "agy tool step 4", "muse tool.shell t1"; several joined by ', ').
10979	function Wait-EngineProcess {
10980	    param($Process, [int]$TimeoutSec, [int]$StallSec = 0, [string]$EventsPath = '', [string]$KickPath = '', [string]$Engine = 'codex')
10981	    $r = [pscustomobject]@{ Exited = $false; Reason = ''; KickLate = $false; Events = 0; LastEvent = $null; Silent = 0; ToolWait = 0; Oversized = 0; ToolOpen = 0; OpenTools = '' }
10982	    $tick = 1000
10983	    $hook = 0
10984	    if ([int]::TryParse((Get-TestHookValue 'CODEX_CONSULT_TEST_WAIT_TICK_MS'), [ref]$hook) -and $hook -gt 0) { $tick = $hook }
10985	    $watch = [System.Diagnostics.Stopwatch]::StartNew()
10986	    $limitMs = [long]$TimeoutSec * 1000
10987	    $stallMs = [long]$StallSec * 1000
10988	    $offset = [long]0
10989	    $carry = [byte[]]@()
10990	    $discarding = $false
10991	    $lastMs = [long]0
10992	    # (wave 27c, D6) the last growth of the stream (never moved by a tool suspension), when the tool
10993	    # calls in flight opened; (wave 28b, D12) how long an open tool call may leave the stream

